result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/bottle.test.jsx", "content": "import { describe, it, expect } from 'vitest'
import { act, create } from '@react-three/test-renderer'
import * as THREE from 'three'
import Bottle, { Bottle as NamedBottle } from '../src/Bottle.jsx'

const EPS = 1e-6

function findGroup(rootObject, name = 'bottle') {
  let found = null
  rootObject.traverse((obj) => {
    if (!found && obj.isGroup && obj.name === name) found = obj
  })
  return found
}

function countDescendants(group) {
  let n = 0
  group.traverse((obj) => {
    n += 1
  })
  return n // includes the group itself
}

function yExtent(group) {
  const box = new THREE.Box3().setFromObject(group)
  return box.max.y - box.min.y
}

describe('<Bottle />', () => {
  it('exports both default and named component', () => {
    expect(typeof NamedBottle).toBe('function')
    expect(NamedBottle).toBe(Bottle)
  })

  it('computes a Box3 over the THREE group with y-extent heightCm / 10 within 1e-6', async () => {
    const renderer = await create(<Bottle heightCm={20} neckRatio={0.4} capColor="#ff0000" />)
    const group = findGroup(renderer.scene)
    expect(group).toBeTruthy()
    expect(yExtent(group)).toBeCloseTo(20 / 10, 12)
    // Box3 min should start at the ground plane
    const box = new THREE.Box3().setFromObject(group)
    expect(box.min.y).toBeCloseTo(0, 12)
  })

  it('rescales the geometry when heightCm changes to 30 on rerender', async () => {
    const renderer = await create(<Bottle heightCm={20} neckRatio={0.4} capColor="#00ff00" />)
    const groupBefore = findGroup(renderer.scene)
    expect(yExtent(groupBefore)).toBeCloseTo(2.0, 12)

    await act(async () => {
      renderer.update(<Bottle heightCm={30} neckRatio={0.4} capColor="#00ff00" />)
    })

    const groupAfter = findGroup(renderer.scene)
    expect(groupAfter).toBeTruthy()
    expect(yExtent(groupAfter)).toBeCloseTo(30 / 10, 12)

    // individual segments must also scale proportionally
    const neck = groupAfter.children.find((c) => c.name === 'neck')
    const cap = groupAfter.children.find((c) => c.name === 'cap')
    // body = H / (1 + q * (1 + capRatio)) ; with q=0.4, capRatio=0.25 -> denom = 1.5
    expect(neck.geometry.parameters.height).toBeCloseTo((0.4 * 3) / 1.5, 12)
    expect(cap.geometry.parameters.height).toBeCloseTo(0.1 * ((0.4 * 3) / 1.5), 12)
  })

  it('cap material color equals new THREE.Color(capColor)', async () => {
    const color = '#e11d48'
    const renderer = await create(<Bottle heightCm={20} neckRatio={0.5} capColor={color} />)
    const group = findGroup(renderer.scene)
    const cap = group.children.find((c) => c.name === 'cap')
    expect(cap).toBeTruthy()
    expect(cap.isMesh).toBe(true)
    expect(cap.material.color).toEqual(new THREE.Color(color))

    await act(async () => {
      renderer.update(<Bottle heightCm={20} neckRatio={0.5} capColor="#2563eb" />)
    })
    const capAfter = findGroup(renderer.scene).children.find((c) => c.name === 'cap')
    expect(capAfter.material.color).toEqual(new THREE.Color('#2563eb'))
  })

  it('does not accumulate leftover children across three rerenders', async () => {
    const props = [
      { heightCm: 15, neckRatio: 0.3, capColor: '#111111' },
      { heightCm: 22, neckRatio: 0.45, capColor: '#222222' },
      { heightCm: 30, neckRatio: 0.6, capColor: '#333333' },
      { heightCm: 8, neckRatio: 0.35, capColor: '#444444' },
    ]

    const renderer = await create(<Bottle {...props[0]} />)
    const counts = []

    for (const p of props) {
      if (p !== props[0]) {
        await act(async () => {
          renderer.update(<Bottle {...p} />)
        })
      }
      const group = findGroup(renderer.scene)
      expect(group).toBeTruthy()
      // every child must still be one of the four named meshes
      const names = group.children.map((c) => c.name).sort()
      expect(names).toEqual(['body-lower', 'body-upper', 'cap', 'neck'])
      counts.push(countDescendants(group))
    }

    // child count is stable across all three rerenders
    expect(new Set(counts).size).toBe(1)
    expect(counts[0]).toBe(5) // group + 4 meshes
  })
})
"})
